mod3 = [{0, 3}, {1, 4}, {2, 5}]
square_mod3 = {x: (x * x) % 3 for x in range(6)}
g = descend(square_mod3, mod3)
assert g == {frozenset({0, 3}): 0, frozenset({1, 4}): 1, frozenset({2, 5}): 1}
assert descend({x: x % 2 for x in range(6)}, mod3) is None
assert descend({x: 'c' for x in range(6)}, mod3) == {frozenset(C): 'c' for C in mod3}
assert descend({0: 1}, [{0}]) == {frozenset({0}): 1}
for x in range(6):
    cls = next(frozenset(C) for C in mod3 if x in C)
    assert g[cls] == square_mod3[x]
